import { readFile, writeFile } from 'node:fs/promises';

// The Docker build context contains this service, not workspace packages.
const source = new URL(
  '../../../packages/session-ingest-contracts/src/kilo2-conversation.ts',
  import.meta.url
);
const target = new URL('../src/shared/kilo2-conversation.ts', import.meta.url);
const content =
  '// Generated by scripts/sync-kilo2-contracts.mjs. Edit the shared package source.\n' +
  (await readFile(source, 'utf8'));
if (process.argv.includes('--check')) {
  if ((await readFile(target, 'utf8')) !== content)
    throw new Error('Run node scripts/sync-kilo2-contracts.mjs');
} else await writeFile(target, content);
